corrected_code:
const express = require('express');
const Agenda = require('agenda');
const { requireMerchantToken } = require('../auth');

const router = express.Router();
const agenda = new Agenda({ db: { address: process.env.MONGO_URI } });

router.post('/api/schedules/payouts', requireMerchantToken, async (req, res) => {
  const { merchantAccountId, executionDate, payoutMethod } = req.body;

  if (req.merchant.accountId !== merchantAccountId && !req.merchant.isGlobalPlatformAdmin) {
    return res.status(403).json({ error: 'Forbidden: cannot schedule payouts for another merchant' });
  }

  const job = await agenda.schedule(executionDate, 'process-merchant-payout', {
    merchantAccountId,
    method: payoutMethod,
    scheduledBy: req.merchant.id,
  });

  res.status(201).json({ scheduledJobId: job.attrs._id, runAt: executionDate });
});
